  ('es-pt', 'f001', 'frase', 'A2', array['cotidiano']::text[], null, '1767d3d1', array['Eu dou o troco.', 'Me dê o mesmo.', 'Somos iguais.', 'Tanto faz.', 'É tudo igual aqui.']::text[]),
  ('es-pt', 'f002', 'frase', 'A1', array['cotidiano']::text[], null, 'a73ff516', array['Nada acontece nunca. / É sempre igual.', 'Nada passa por aqui. / Está parado.', 'Não passe por aí. / Evite o lugar.', 'Não tem problema. / Tudo bem.', 'Não vai dar certo. / Vai falhar.']::text[]),
  ('es-pt', 'f003', 'frase', 'B1', array['cotidiano']::text[], null, 'e997dd88', array['Espero ficar farta de comer.', 'Espero ficar farto de comer.', 'Estou cheia de comida agora.', 'Estou cheio de comida agora.', 'Estou de saco cheio de esperar.', 'Estou disposta a esperar mais.', 'Estou disposto a esperar mais.', 'Tenho bastante tempo para esperar.']::text[]),
  ('es-pt', 'f004', 'frase', 'B1', array['expressão']::text[], null, 'af51ed14', array['Levante a mão. / Peça a palavra.', 'Me dá uma mão. / Me ajuda.', 'Me jogue a mão. / Me arremesse.', 'Segure a minha mão. / Vamos atravessar.', 'Solte a minha mão. / Me largue.']::text[]),
  ('es-pt', 'f005', 'frase', 'B1', array['cotidiano']::text[], null, '969a35a6', array['Cheguei tarde.', 'Ele me atrasou.', 'Estou ficando atrasado.', 'Faço isso mais tarde.', 'Me deixou tarde.']::text[]),
  ('es-pt', 'f007', 'frase', 'B1', array['expressão']::text[], null, '7ba32d9e', array['Está chovendo muito.', 'Está com a cabeça nas alturas do sucesso.', 'Está muito feliz.', 'Está no mundo da lua.', 'Está voando de avião.']::text[]),
  ('es-pt', 'f008', 'frase', 'B1', array['cotidiano']::text[], null, 'e318f23e', array['Estou sonhando. / Não é real.', 'Está tocando. / O som saiu.', 'Me parece familiar. / Já ouvi isso.', 'Me soa mal. / Não gostei.', 'Toca para mim. / Faça um som.']::text[]),
  ('es-pt', 'f009', 'frase', 'B1', array['gramática']::text[], null, '68c74de1', array['Com certeza eu vou.', 'No melhor dos casos, fui.', 'Prefiro não ir.', 'Talvez eu vá.', 'Vou da melhor forma.']::text[]),
  ('es-pt', 'f010', 'frase', 'B1', array['gramática']::text[], null, 'e30d3f4d', array['Estou há dois anos aqui.', 'Levarei dois anos.', 'Levo dois anos daqui.', 'Passei por aqui há dois anos.', 'Trouxe dois anos aqui.']::text[]),
  ('es-pt', 'f011', 'frase', 'A2', array['gramática']::text[], null, '3f100e4f', array['Acabei de chegar.', 'Acabo de sair.', 'Chego no final.', 'Terminei a chegada.', 'Vou acabar chegando.']::text[]),
  ('es-pt', 'f012', 'frase', 'B1', array['expressão']::text[], null, '2763338b', array['Ele caiu bem. / A roupa ficou boa.', 'Ele caiu em cima de mim. / Me derrubou.', 'Ele me faz bem. / Melhora minha saúde.', 'Eu caio bem ali. / O lugar me serve.', 'Eu simpatizo com ele. / Acho ele gente boa.']::text[]),
  ('es-pt', 'f013', 'frase', 'B2', array['expressão']::text[], null, 'ec331475', array['Abrir o bico. / Contar o segredo.', 'Dar uma mancada. / Pisar na bola.', 'Meter o bedelho. / Dar palpite.', 'Meter o pé na porta. / Forçar a entrada.', 'Pôr o pé na estrada. / Viajar.']::text[]),
  ('es-pt', 'f015', 'frase', 'B2', array['expressão']::text[], null, 'c0cccf82', array['Estender a toalha. / Secar ao sol.', 'Jogar a toalha. / Desistir.', 'Lavar a roupa suja. / Brigar em casa.', 'Puxar a toalha. / Arrastar.', 'Secar as mãos. / Se limpar.']::text[]),
  ('es-pt', 'f016', 'frase', 'B2', array['expressão']::text[], null, '37601e0b', array['Fala pelos cotovelos.', 'Não fala nada.', 'Não tem papas na língua.', 'Tem a língua presa.', 'É muito educado.']::text[]),
  ('es-pt', 'f017', 'frase', 'B2', array['expressão']::text[], null, 'edac024b', array['O pão acabou. / Comeram tudo.', 'É caro demais. / Não compensa.', 'É coisa antiga. / Já passou.', 'É moleza. / É sopa.', 'É pão-duro. / Não gasta nada.']::text[]),
  ('es-pt', 'f018', 'frase', 'B1', array['expressão']::text[], null, 'e48eb6f3', array['Custa os olhos da cara.', 'Custa pouco.', 'Custa um olho roxo.', 'Dói o olho.', 'Vale a pena olhar.']::text[]),
  ('es-pt', 'f020', 'frase', 'B2', array['expressão']::text[], null, 'd1161762', array['Acertar em cheio.', 'Bater o prego.', 'Errar o alvo.', 'Ficar preso.', 'Pregar o prego.']::text[]),
  ('es-pt', 'f021', 'frase', 'B2', array['expressão']::text[], null, 'feb85b41', array['Descanse um pouco. / Recarregue as forças.', 'Empilhe tudo. / Organize as caixas.', 'Ligue o aparelho. / Aperte o botão.', 'Ponha as pilhas. / Troque a bateria.', 'Se liga. / Corre atrás.']::text[]),
  ('es-pt', 'f022', 'frase', 'B2', array['expressão']::text[], null, 'a7e12375', array['Encarar de frente.', 'Engordar os olhos.', 'Fazer vista grossa.', 'Olhar com atenção.', 'Ver de longe.']::text[]),
  ('es-pt', 'f023', 'frase', 'B2', array['expressão']::text[], null, '35691147', array['Vamos ao grão de café.', 'Vamos ao mercado.', 'Vamos com calma.', 'Vamos direto ao ponto.', 'Vamos plantar.']::text[]),
  ('es-pt', 'f024', 'frase', 'B2', array['expressão']::text[], null, '68f4ee3b', array['Estou acabada. / Estou exausta.', 'Estou acabado. / Estou exausto.', 'Estou de mau humor. / Estou irritada.', 'Estou de mau humor. / Estou irritado.', 'Estou empoeirada. / Estou suja.', 'Estou empoeirado. / Estou sujo.', 'Estou sem dinheiro. / Estou quebrada.', 'Estou sem dinheiro. / Estou quebrado.', 'Fiz uma poeira. / Levantei pó.']::text[]),
  ('es-pt', 'f025', 'frase', 'C1', array['expressão']::text[], null, '5bb61814', array['Por causa das moscas.', 'Por pura teimosia.', 'Por via das dúvidas.', 'Se houver moscas.', 'Sem mais nem menos.']::text[]),
  ('es-pt', 'f026', 'frase', 'C1', array['expressão']::text[], null, '7a4d0b22', array['Aos poucos e com muita calma. / Bem devagar.', 'Com as melhores intenções. / De coração bem aberto.', 'Das boas às primeiras. / Bem na ordem certa.', 'De uma hora para outra. / Sem mais nem menos.', 'Em primeiro lugar de todos. / Antes de tudo.']::text[]),
  ('es-pt', 'f028', 'frase', 'C1', array['expressão']::text[], null, '0250335d', array['Não acerta uma.', 'Não chuta a bola.', 'Não joga futebol.', 'Não pega no pé.', 'Não sai do lugar.']::text[]),
  ('es-pt', 'f029', 'frase', 'C1', array['gíria', 'Espanha']::text[], null, '861d3931', array['Que bagunça!', 'Que caro!', 'Que chatice!', 'Que choro!', 'Que pechincha!']::text[]),
  ('es-pt', 'f033', 'frase', 'B2', array['expressão']::text[], null, '41bb65da', array['Gosto muito de pepino.', 'Importo pepinos.', 'Isso me preocupa.', 'Não estou nem aí.', 'É um problema sério.']::text[]),
  ('es-pt', 'f034', 'frase', 'B2', array['expressão']::text[], null, 'c3a93a19', array['Abrindo e fechando a porta.', 'Com os olhos fechados.', 'Devagar e sempre.', 'Num piscar de olhos.', 'Sem ver nada.']::text[]),
  ('es-pt', 'f036', 'frase', 'A1', array['primeiros passos', 'cotidiano']::text[], null, 'c9401f9f', array['Como vai? / E aí?', 'O que é isso? / Explique.', 'Qual deles? / Escolha um.', 'Quanto custa? / Qual o preço?', 'Que tal isso? / Gostou?']::text[]),
  ('es-pt', 'f037', 'frase', 'A2', array['gramática']::text[], null, 'dc32fda9', array['Consegui dormir bem essa noite.', 'Estou com vontade de dormir.', 'Estou dormindo neste exato momento.', 'Ganhei uma soneca de brinde.', 'Tenho que ir dormir agora.']::text[]),
  ('es-pt', 'f038', 'frase', 'A1', array['gramática']::text[], null, '229eabb2', array['Estou com muito frio.', 'Está muito frio.', 'Faz frio há muito tempo.', 'Fez frio ontem.', 'Vai fazer frio.']::text[]),
  ('es-pt', 'f039', 'frase', 'A1', array['cotidiano']::text[], null, 'e7bcfd01', array['Deixe-me entrar.', 'Tenho ido.', 'Tenho que ir aí.', 'Tenho que ir embora.', 'Vou levar isso.']::text[]),
  ('es-pt', 'f040', 'frase', 'B1', array['gramática']::text[], null, '04381779', array['Ele me esqueceu.', 'Eu esqueci.', 'Fui esquecido.', 'Não lembro dele.', 'Vou esquecer.']::text[]),
  ('es-pt', 'f041', 'frase', 'B1', array['gramática']::text[], null, '53ab2d40', array['Ainda tenho dois. / Sobraram dois.', 'Dei dois embora. / Me livrei deles.', 'Faltam dois para mim. / Preciso de dois.', 'Fico com dois. / Escolhi esses.', 'Quero dois. / Me traga dois.']::text[]),
  ('es-pt', 'f043', 'frase', 'B2', array['gramática']::text[], null, '648f8899', array['Eu não sei nada.', 'Não quero saber.', 'Que eu saiba, não.', 'Sei que não.', 'Só eu sei.']::text[]),
  ('es-pt', 'f045', 'frase', 'C1', array['gramática', 'subjuntivo']::text[], null, 'eecce1b1', array['Antes ele tivesse vindo ontem.', 'Ele disse que viria amanhã.', 'Espero que ele chegue amanhã cedo.', 'Quem me dera que ele viesse amanhã.', 'Tomara que ele venha amanhã.']::text[]),
  ('es-pt', 'f046', 'frase', 'C1', array['gramática', 'condicional']::text[], null, 'dc1cb8b7', array['Ao saber, não venho.', 'Não soube e não vim.', 'Por ter sabido, não vim.', 'Sabendo disso, virei.', 'Se eu soubesse, não teria vindo.']::text[]),
  ('es-pt', 'f047', 'frase', 'B2', array['gramática', 'subjuntivo']::text[], null, 'e34f1f43', array['Ele não tenta e por isso não consegue.', 'Ele só vai conseguir se tentar de novo.', 'Ele tentou bastante e acabou conseguindo.', 'Por mais que tente, ele não consegue.', 'Quanto mais ele tenta, mais consegue.']::text[]),
  ('es-pt', 'f048', 'frase', 'B2', array['gramática', 'subjuntivo']::text[], null, '4fb583d6', array['Assim que nada passou.', 'Como nada aconteceu.', 'Como se nada acontecesse.', 'Como se nada fosse acontecer.', 'Como se nada tivesse acontecido.']::text[]),
  ('es-pt', 'f049', 'frase', 'B2', array['gramática', 'subjuntivo']::text[], null, 'fa89dadf', array['Ainda que chovia, eu ia.', 'Como chove, eu vou.', 'Embora chovesse, fui.', 'Mesmo que chova, eu irei.', 'Se chover, eu vou.']::text[]),
  ('es-pt', 'f051', 'frase', 'B1', array['gramática', 'pronomes']::text[], null, '41525227', array['Disseram-me ontem.', 'Ele me disse ontem.', 'Eu disse a ele hoje.', 'Eu disse isso a ele ontem.', 'Eu disse isso para você ontem.']::text[]),
  ('es-pt', 'f052', 'frase', 'A2', array['gramática']::text[], null, '4cf49ce6', array['Há quem faça isso.', 'Já foi feito.', 'Pode-se fazer depois.', 'Vamos fazer depois.', 'É preciso fazer isso agora.']::text[]),
  ('es-pt', 'f053', 'frase', 'B1', array['gramática']::text[], null, 'a974176a', array['Estudei espanhol três anos atrás.', 'Estudo espanhol há três anos.', 'Levei três anos estudando espanhol.', 'Terminei o espanhol em três anos.', 'Vou estudar espanhol por três anos.']::text[]),
  ('es-pt', 'f054', 'frase', 'B2', array['provérbio']::text[], null, '23583ef1', array['Há males que vêm para bem.', 'Nem tudo que vem é bom.', 'Não há mal nenhum.', 'O bem não vem do mal.', 'Todo mal é bem-vindo.']::text[]),
  ('es-pt', 'f055', 'frase', 'B1', array['provérbio']::text[], null, '4c687adc', array['Deus ajuda a quem se ajuda.', 'Deus ajuda quem cedo madruga.', 'Deus escreve certo por linhas tortas.', 'Quem dorme cedo, acorda cedo.', 'Quem espera sempre alcança.']::text[]),
  ('es-pt', 'f056', 'frase', 'C1', array['provérbio']::text[], null, 'a0b35a4b', array['Quem abraça, aperta pouco.', 'Quem aperta muito, perde.', 'Quem cala consente.', 'Quem muito quer, nada tem.', 'Quem tem pouco, quer muito.']::text[]),
  ('es-pt', 'f057', 'frase', 'C1', array['expressão']::text[], null, 'b50f5c94', array['Deram um gato a ele.', 'Ele comprou um gato.', 'Presentearam com um coelho.', 'Trocaram o gato pela lebre dele.', 'Venderam gato por lebre a ele.']::text[]),
  ('es-pt', 'f058', 'frase', 'B2', array['expressão']::text[], null, 'a06ac231', array['Estão brigados. / Não se falam.', 'São iguaizinhos. / Parecem gêmeos.', 'São parentes. / Têm o mesmo sangue.', 'São rivais. / Vivem competindo.', 'São unha e carne. / São inseparáveis.']::text[]),
  ('es-pt', 'f059', 'frase', 'C1', array['expressão']::text[], null, '2fda3d82', array['Não ande pelo mato. / É perigoso.', 'Não fale tão alto. / Baixe o tom.', 'Não fique enrolando. / Vá direto ao ponto.', 'Não se meta nisso. / Deixe para lá.', 'Não suba nos galhos. / Pode quebrar.']::text[]),
  ('es-pt', 'f060', 'frase', 'C1', array['expressão']::text[], null, 'c7ff1760', array['Ele sempre consegue o que quer.', 'Ele sempre sai com a namorada.', 'Ele sempre sai perdendo.', 'Ele sempre sai sozinho.', 'Ele sempre se dá mal.']::text[]),
  ('es-pt', 'f062', 'frase', 'B2', array['expressão']::text[], null, '0ec88f08', array['Fiquei duro. / Sem dinheiro nenhum.', 'Fiquei firme. / Não mudei de ideia.', 'Fiquei na pedra. / Sentei ali.', 'Fiquei pasmo. / Fiquei chocado.', 'Peguei uma pedra. / Levantei do chão.']::text[]),
  ('es-pt', 'f063', 'frase', 'B2', array['gíria']::text[], null, '5a048b90', array['Estou animado. / Cheio de energia.', 'Estou de baixa. / Afastado do trabalho.', 'Estou descendo. / Vou de elevador.', 'Estou no fundo do poço. / Sem dinheiro.', 'Estou pra baixo. / Estou desanimado.']::text[]),
  ('es-pt', 'f064', 'frase', 'B2', array['expressão']::text[], null, 'd2908f83', array['Acender a lareira.', 'Apagar o fogo.', 'Botar lenha na fogueira.', 'Cozinhar na lenha.', 'Jogar água fria.']::text[]),
  ('es-pt', 'f065', 'frase', 'C2', array['expressão']::text[], null, 'e26d42dd', array['Fez aos poucos. / Um pedaço a cada dia.', 'Fez com muito cuidado. / Com todo o capricho.', 'Fez de qualquer jeito. / A torto e a direito.', 'Fez durante a noite. / Quando todos já dormiam.', 'Fez tudo em dobro. / Duas vezes bem seguidas.']::text[]),
  ('es-pt', 'f067', 'frase', 'B2', array['expressão']::text[], null, 'c4aca83d', array['A muito custo consegui terminar.', 'Com facilidade terminei.', 'Nem consegui terminar.', 'Terminei com pena.', 'Terminei duro de cansaço.']::text[]),
  ('es-pt', 'f069', 'frase', 'B1', array['cotidiano', 'Espanha']::text[], null, 'cf1bde26', array['Beleza, a gente fica até as oito.', 'Beleza, a gente se encontra às oito.', 'Certo, sobraram oito lugares para nós.', 'Combinado, vale a pena chegar às oito.', 'Tudo bem, isso vale oito reais.']::text[]),
  ('es-pt', 'f070', 'frase', 'A2', array['cotidiano']::text[], null, '63b2454d', array['Ainda bem que você chegou.', 'Faltou pouco para você chegar.', 'Menos mal do que parecia.', 'Pior que você chegou.', 'Você chegou mal.']::text[]),
