  ('es-pt', 'f071', 'frase', 'A1', array['primeiros passos', 'cotidiano']::text[], null, '8c1814e3', array['Como você me chamou?', 'Como você se chama?', 'Como você se chateia?', 'Por que você chamou?', 'Quando você chamou?']::text[]),
  ('es-pt', 'f072', 'frase', 'A1', array['primeiros passos', 'cotidiano', 'viagem']::text[], null, '7975dfcf', array['Como chego ao banho?', 'De onde vem o banho?', 'Onde fica a banheira?', 'Onde fica o banheiro?', 'Quando abre o banheiro?']::text[]),
  ('es-pt', 'f073', 'frase', 'A1', array['cotidiano']::text[], null, 'fb59e52c', array['Não atendo ninguém.', 'Não entendi ontem.', 'Não entendo nada.', 'Não entrego nada.', 'Não pretendo nada.']::text[]),
  ('es-pt', 'f074', 'frase', 'A1', array['primeiros passos', 'cotidiano', 'viagem']::text[], null, 'ecad668b', array['Quando custou?', 'Quanto cabe?', 'Quanto conta?', 'Quanto custa?', 'Quanto pesa?']::text[]),
  ('es-pt', 'f075', 'frase', 'A1', array['cotidiano']::text[], null, '7c3a0c73', array['Estou com fome.', 'Estou com frio.', 'Estou com pressa.', 'Estou com sede.', 'Estou com sono.']::text[]),
  ('es-pt', 'f076', 'frase', 'A1', array['primeiros passos', 'cotidiano']::text[], null, 'ca33de90', array['Até amanhã.', 'Até de manhã.', 'Até mais tarde.', 'Boa manhã.', 'Desde amanhã.']::text[]),
  ('es-pt', 'f077', 'frase', 'A2', array['cotidiano']::text[], null, '0c12b7b5', array['Eu acordei agora.', 'Eu acordo cedo.', 'Eu combinei antes.', 'Eu concordo.', 'Eu me lembro disso.']::text[]),
  ('es-pt', 'f078', 'frase', 'A2', array['falso-amigo', 'verbo']::text[], 'p021', 'c60d56ae', array['Não anotei o nome dele.', 'Não combinei nada com ele.', 'Não concordo com o nome dele.', 'Não me acordaram a tempo.', 'Não me lembro do nome dele.']::text[]),
  ('es-pt', 'f079', 'frase', 'A2', array['cotidiano']::text[], null, '09f0fa0e', array['Você pode falar mais alto?', 'Você pode lavar as mãos?', 'Você pode me dar uma mão?', 'Você pode me esperar aqui?', 'Você pode me estender a mão?']::text[]),
  ('es-pt', 'f080', 'frase', 'A2', array['expressão']::text[], null, '7a95fe1a', array['Está chovendo canivete.', 'Está chovendo devagar.', 'Está chovendo em cântaros.', 'Está garoando bem pouco.', 'Está prestes a chover.']::text[]),
  ('es-pt', 'f081', 'frase', 'A2', array['cotidiano']::text[], null, '6f431014', array['Não se apresse.', 'Não se incomode em vir.', 'Não se ocupe disso.', 'Não se preocupe.', 'Não se prepare ainda.']::text[]),
  ('es-pt', 'f082', 'frase', 'B1', array['gramática', 'verbo']::text[], 'p082', 'd1824ee6', array['Consigo acordar cedo.', 'Costumo acordar cedo.', 'Detesto acordar cedo.', 'Preciso acordar cedo.', 'Quero acordar cedo.']::text[]),
  ('es-pt', 'f083', 'frase', 'B1', array['cotidiano', 'Espanha']::text[], null, '94883e7d', array['Você aguenta mais um café hoje?', 'Você está a fim de um café?', 'Você já tomou um café hoje?', 'Você prefere um café ou chá?', 'Você prepara um café para mim?']::text[]),
  ('es-pt', 'f085', 'frase', 'B1', array['verbo']::text[], 'p087', 'fd2de1e6', array['Cheguei duas horas atrasado.', 'Demorei duas horas para chegar.', 'Esperei duas horas para sair.', 'Fiquei duas horas por lá.', 'Saí duas horas mais cedo.']::text[]),
  ('es-pt', 'f086', 'frase', 'B1', array['expressão']::text[], null, '63665235', array['Me custa caro cozinhar.', 'Me dá fome cozinhar.', 'Me dá trabalho cozinhar.', 'Me faz bem cozinhar.', 'Tenho jeito para cozinhar.']::text[]),
  ('es-pt', 'f087', 'frase', 'B2', array['expressão']::text[], null, '64071005', array['Ao fim da conta, pagamos.', 'Em resumo, conte comigo.', 'No fim das contas, tanto faz.', 'No fim do mês, pago tudo.', 'Para fechar a conta, tanto faz.']::text[]),
  ('es-pt', 'f088', 'frase', 'B2', array['expressão']::text[], null, '40a2bb81', array['Já que foi visto, não virá.', 'Pela visão dele, não venderá.', 'Pelo que vi, ele veio.', 'Pelo visto, ele não virá.', 'Pelo visto, ele vendeu.']::text[]),
